sys_script_client.script:
// Nome do campo que dispara o evento onChange: 'data'
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    var cursoId = g_form.getValue('course'); // Obtém o curso do formulário
    var dataTreinamento = newValue; // Nova data selecionada

    var ga = new GlideAjax('TrainingValidator');
    ga.addParam('sysparm_name', 'isTrainingDateAvailable');
    ga.addParam('course', cursoId);
    ga.addParam('training_date', dataTreinamento);

    ga.getXMLAnswer(function(response) {
        if (response === 'false') {
            g_form.addErrorMessage('Já existe um treinamento deste curso programado para esta data.');
            g_form.clearValue('training_date'); // Limpa o campo se a data for inválida
        }
    });
}
